"""Campaign compiler, typed replay, filtering, and state preparation.

The pipeline is: build the type table and modules, compose one plan per entry
(module order, declaration names, symbolic slots, filter applications), then
replay every recorded run through strict transport decoding, flag
attestation, predicate filtering, state preparation and corpus
deduplication.  Model results are witnesses only; the identity of a test is
the entry plus its recovered input values.
"""
from .ast import build_modules, build_types, compile_predicate
from .composer import DependencyGraph
from .errors import InvalidCampaign, InvalidTest
from .oracles import build_harness, read_value
from .run import identity_key
from .state import Machine
from .wire import assign, decode

_MISSING = object()


class Plan(object):
    """One compiled entry plan."""

    __slots__ = ("entry", "module", "modules", "types", "slots", "flag",
                 "variables", "harness", "apps", "param_names")

    def __init__(self, entry, module, modules, types, harness, apps):
        self.entry = entry
        self.module = module
        self.modules = modules
        self.types = types
        self.harness = harness
        self.slots = harness.slots
        self.flag = harness.flag
        self.variables = harness.variables
        self.apps = apps
        self.param_names = harness.param_names

    def dump(self):
        return {
            "entry": self.entry,
            "modules": self.modules,
            "types": self.types,
            "slots": self.slots,
            "flag": self.flag,
            "variables": self.variables,
        }


class Campaign(object):
    """The whole offline campaign: compilation and replay certificate."""

    def __init__(self, document):
        if not isinstance(document, dict):
            raise InvalidCampaign("campaign must be an object")
        self.table = build_types(document.get("types"))
        self.modules = build_modules(document.get("modules"), self.table)
        self.graph = DependencyGraph(self.modules, document.get("calls"),
                                     document.get("pipes"))
        entries = document.get("entries")
        if not isinstance(entries, list):
            raise InvalidCampaign("entries must be a list")
        if len(entries) > 32:
            raise InvalidCampaign("too many entries")
        for entry in entries:
            if not isinstance(entry, str) or entry not in self.modules:
                raise InvalidCampaign("unknown entry " + repr(entry))
        if len(set(entries)) != len(entries):
            raise InvalidCampaign("duplicate entry")
        self.entries = list(entries)
        machine = document.get("machine")
        self.machine = Machine(machine) if machine is not None else None
        self.runs = document.get("runs")
        if not isinstance(self.runs, list):
            raise InvalidCampaign("runs must be a list")
        self.plans = [self._plan(entry) for entry in self.entries]
        self.plans_by_entry = {plan.entry: plan for plan in self.plans}
        self._guard_cache = {}
        self._analysis = {}
        self._preparation = {}

    # -- compilation -------------------------------------------------------

    def _plan(self, entry):
        """Compile one entry: module order, declarations, slots, filters."""
        module = self.modules[entry]
        order = self.graph.compile_order(entry)
        declarations = self.graph.type_declarations(order, self.modules)
        applications = self.graph.composed_applications(entry)
        flag_needed = bool(self.graph.pipes_by_target.get(entry))
        harness = build_harness(module, flag_needed)
        return Plan(entry, module, order, declarations, harness, applications)

    # -- replay ------------------------------------------------------------

    def certificate(self):
        records = []
        corpus = []
        index_of = {}
        analysis = self._analysis
        for number, run in enumerate(self.runs):
            if not isinstance(run, dict):
                raise InvalidCampaign("run must be an object")
            entry = run.get("entry")
            plan = self.plans_by_entry.get(entry)
            if plan is None:
                records.append({"status": "INVALID_TEST"})
                continue
            try:
                objects = assign(decode(run.get("ktest")), plan.harness.leaves)
                values = self._recover(plan, objects)
            except InvalidTest:
                records.append({"status": "INVALID_TEST"})
                continue
            except Exception as exc:  # pragma: no cover - defensive only
                self._warn("run %d: %r" % (number, exc))
                records.append({"status": "INVALID_TEST"})
                continue
            key = identity_key(entry, plan.param_names, values)
            verdict = analysis.get(key)
            if verdict is None:
                verdict = self._analyse(plan, key, values)
                analysis[key] = verdict
            if plan.flag is not None:
                # The flag attests to pipe acceptance only; a mismatch
                # invalidates the test even if a predicate would reject it.
                if (objects[plan.flag] == 1) != (not verdict[1]):
                    records.append({"status": "INVALID_TEST"})
                    continue
            if verdict[2] != "OK":
                records.append({"status": verdict[2]})
                continue
            cost, commands = verdict[3], verdict[4]
            result = None
            if plan.harness.result is not None:
                _, descriptor = plan.harness.result
                result = read_value(descriptor, objects)
            case = index_of.get(key)
            if case is None:
                case = len(corpus)
                index_of[key] = case
                corpus.append({
                    "entry": entry,
                    "inputs": {name: values[name] for name in plan.param_names},
                    "cost": cost,
                    "commands": commands,
                    "witnesses": [number],
                })
                records.append({"status": "READY", "case": case,
                                "model_result": result})
            else:
                corpus[case]["witnesses"].append(number)
                records.append({"status": "DUPLICATE", "case": case,
                                "model_result": result})
        return {
            "plans": [plan.dump() for plan in self.plans],
            "records": records,
            "corpus": corpus,
        }

    def _recover(self, plan, objects):
        """Recover the entry's input values from a validated assignment."""
        values = {}
        for name, descriptor in plan.harness.inputs:
            values[name] = read_value(descriptor, objects)
        return values

    def _analyse(self, plan, key, values):
        """`(accepts, filters accept, status, cost, commands)` per input.

        The verdict depends only on the recovered input values, so it is
        cached by corpus identity and shared by every witness of one input.
        """
        module = plan.module
        accepted = True
        if module.requires is not None and not module.requires(values):
            accepted = False
        filters = True
        if accepted or plan.flag is not None:
            filters = self._filters_accept(plan, values)
        if not accepted or not filters:
            return (accepted, filters, "FILTERED", 0, [])
        if self.machine is None:
            return (accepted, filters, "OK", 0, [])
        preparation = self._preparation.get(key, _MISSING)
        if preparation is _MISSING:
            preparation = self._prepare(plan, values)
            self._preparation[key] = preparation
        if preparation is None:
            return (accepted, filters, "UNREACHABLE", 0, [])
        cost, commands = preparation
        message = values.get(self.machine.message_param)
        if not isinstance(message, str):
            message = ""
        return (accepted, filters, "OK", cost, list(commands) + [message])

    def _filters_accept(self, plan, values):
        """Every composed filter application accepts, transitively."""
        for name, mapping in plan.apps:
            module = self.modules[name]
            predicate = module.requires
            if predicate is None:
                continue
            environment = {}
            for pname, _ in module.params:
                source = mapping.get(pname)
                if source is None:
                    return False
                environment[pname] = values[source]
            if not predicate(environment):
                return False
        return True

    def _guards(self, entry):
        """Compile the machine's distinct guards against one entry's scope."""
        compiled = self._guard_cache.get(entry)
        if compiled is None:
            machine = self.machine
            scope = self.modules[entry].scope
            compiled = [None if source is None else
                        compile_predicate(source, scope, self.table)
                        for source in machine.guard_sources]
            self._guard_cache[entry] = compiled
        return compiled

    def _prepare(self, plan, values):
        """Optimal preamble for this entry and recovered inputs, or None."""
        machine = self.machine
        desired = values.get(machine.state_param)
        if not machine.has_guards:
            return machine.prepare(desired, None)
        guards = self._guards(plan.entry)
        results = [True if fn is None else bool(fn(values)) for fn in guards]
        return machine.prepare(desired, machine.enabled_vector(results))

    @staticmethod
    def _warn(message):
        import sys
        sys.stderr.write("campaign warning: %s\n" % (message,))


def execute(campaign):
    """Compile one campaign and return its replay certificate."""
    return Campaign(campaign).certificate()
